import {escapeHTML as e,number,relativeDate} from '../core/utils.js';
import {SYMBOLS} from '../core/seed.js';
import {validateDiagram,reconcileBOM,diffDiagrams,adjacency} from '../core/analysis.js';
import {profile} from '../core/data.js';
import {button as b,ib,badge,heading,tabs,field,selectField,table,metric,notice,chart,empty} from './components.js';
import {icon} from './icons.js';
export const routes=[['overview','Overview','home'],['ontology','Ontology','network'],['data','Data workspace','database'],['pipelines','Pipelines','flow'],['pid','P&ID Studio','pid'],['agents','Agent studio','spark'],['logic','Logic & actions','code'],['evaluations','Evaluations','flask'],['applications','Applications','grid'],['automations','Automations','bolt'],['observability','Observability','chart'],['governance','Governance','shield'],['settings','Models & settings','settings']];
export function shell(state,ui){const nav=(list)=>list.map(([id,label,ic])=>`<button class="nav-item ${ui.route===id?'active':''}" data-route="${id}">${icon(ic,16)}<span>${label}</span>${id==='pid'?'<span class="nav-dot"></span>':''}</button>`).join('');return `<div class="app"><aside class="rail" aria-label="Workspace navigation"><button class="rail-button rail-logo" data-route="overview" title="Stratum Intelligence">${icon('layers',26)}</button>${[['overview','home','Overview'],['pid','pid','P&ID Studio'],['ontology','network','Ontology'],['agents','spark','Agent studio'],['data','database','Data workspace'],['pipelines','flow','Pipelines']].map(([id,ic,label])=>`<button class="rail-button ${ui.route===id?'active':''}" data-route="${id}" title="${label}" aria-label="${label}">${icon(ic,19)}</button>`).join('')}<div class="rail-line"></div><button class="rail-button" data-action="search" title="Search workspace">${icon('search',19)}</button><div class="spacer"></div><button class="rail-button" data-action="theme" title="Toggle light and dark theme">${icon(state.theme==='dark'?'sun':'moon',18)}</button><button class="rail-button" data-action="help" title="Help and keyboard shortcuts">${icon('help',18)}</button><button class="rail-button" data-route="settings" title="Local workspace settings"><span class="rail-avatar">NL</span></button></aside><aside class="sidebar"><div class="brand"><b>stratum<span style="color:var(--accent)">.</span></b><small>INTELLIGENCE PLATFORM</small></div><button class="workspace-switch" data-action="workspace"><span class="mini-avatar">${icon('layers',16)}</span><span><strong>${e(state.name)}</strong><small>Engineering workspace</small></span>${icon('down',12)}</button><div class="nav-caption">Workspace</div>${nav(routes.slice(0,5))}<div class="nav-caption">Build & operate</div>${nav(routes.slice(5,10))}<div class="nav-caption">Manage</div>${nav(routes.slice(10))}<div class="sidebar-bottom"><div class="local-card"><span class="green-dot"></span>Local-first workspace<br>Sample data · stored on this device<br><button class="text-button" data-action="export-workspace" style="margin-top:7px;font-size:9px">Back up workspace ${icon('upRight',11)}</button></div></div></aside><header class="topbar"><div class="breadcrumbs">${icon('folder',14)}<span>${e(state.name)}</span>${icon('chevron',10)}<strong id="route-crumb">${routes.find(r=>r[0]===ui.route)?.[1]||'Workspace'}</strong></div><div class="top-actions"><button class="global-search" data-action="search">${icon('search',14)}<span>Search your workspace…</span><kbd>⌘ K</kbd></button>${badge('LOCAL WORKSPACE')}<button class="icon-button" data-action="notifications" title="Review pending actions">${icon('bell',16)}</button><button class="icon-button" data-action="help" title="Help">${icon('help',16)}</button></div></header><main id="main" class="main"></main><footer class="statusbar"><div class="status-section"><span><span class="green-dot"></span><span id="save-status">Stored locally</span></span><span>${icon('shield',10)}<span id="role-status">${e(state.settings.role)} · local workspace</span></span></div><div class="status-section"><span id="engine-status">Initializing rendering engine</span><span id="draw-stats"></span><span>STRATUM 0.1</span></div></footer></div>`;}
export function pidView(state,ui,diagram){const findings=validateDiagram(diagram),recon=reconcileBOM(diagram,state.datasets.find(d=>d.id==='ds-bom')?.rows||[]);const top=heading('P&ID Studio','Turn engineering drawings into connected operational intelligence.','pid',b('Import drawing','import-drawing','upload')+b('Export','export-drawing','download','', 'class="heading-actions-secondary"')+b('Publish to ontology','publish','network','primary'),true)+tabs([['drawing','Drawing'],['components','Components',diagram.nodes.length],['bom','BOM reconciliation',recon.filter(r=>r.status!=='matched').length],['revisions','Revisions',diagram.revisions.length]],ui.pidTab,'pid');
 if(ui.pidTab==='components')return top+`<section class="tab-content"><div class="row justify mb"><div class="search-input" style="width:260px">${icon('search',14)}<input id="component-search" placeholder="Filter by tag, name, or type…" value="${e(ui.componentFilter||'')}"></div><div class="actions">${b('Add component','add-component','plus')}${b('Export register','export-components','download')}</div></div><div class="panel" id="components-table">${componentTable(diagram,ui)}</div><div class="mt">${notice('Select a component to open it on the drawing. Imported detections remain unverified until explicitly reviewed.')}</div></section>`;
 if(ui.pidTab==='bom')return top+`<section class="tab-content"><div class="summary-grid">${metric('Exact matches',recon.filter(r=>r.status==='matched').length,'Normalized tag matches','checkCircle')}${metric('Properties differ',recon.filter(r=>r.status==='mismatch').length,'Stored line-class differences','warning')}${metric('Not in BOM',recon.filter(r=>r.status==='missing').length,'Drawing components requiring review','pid')}${metric('Not in drawing',recon.filter(r=>r.status==='extra').length,'Unmatched BOM rows','table')}</div><div class="panel"><div class="panel-head"><div><h3>Bill of materials reconciliation</h3><p class="subheading">Exact tag matching. Suggestions never overwrite engineering records.</p></div><div class="actions">${b('Import BOM','import-bom','upload')}${b('Export results','export-bom','download')}</div></div>${table(recon,[{key:'tag',label:'Component tag',render:v=>`<span class="tag-badge">${e(v)}</span>`},{key:'status',label:'Match status',render:v=>badge(v,v)},{key:'bomTag',label:'BOM tag'},{key:'details',label:'Evidence'},{key:'candidate',label:'Possible candidate'}])}</div></section>`;
 if(ui.pidTab==='revisions'){const previous=diagram.revisions.at(-1),diff=previous?diffDiagrams(previous.snapshot,diagram):[];return top+`<section class="tab-content"><div class="row justify mb"><div><h2>Drawing history</h2><p class="subheading">Explicit baselines, field-level differences, and reversible edits.</p></div>${b('Save revision baseline','save-revision','save','primary')}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Changes since ${previous?e(previous.name):'the latest baseline'}</h3>${badge(`${diff.length} changes`)}</div>${previous?table(diff,[{key:'tag',label:'Tag'},{key:'type',label:'Change',render:v=>badge(v,v==='removed'?'error':'blue')},{key:'fields',label:'Changed fields',render:v=>e(v.join(', ')||'Entire component')}],{empty:'No changes since this baseline.'}):empty('No baseline yet','Save the current drawing as a revision, then move or edit components to compare changes.')}</div><div class="panel"><div class="panel-head"><h3>Saved baselines</h3></div>${diagram.revisions.length?diagram.revisions.toReversed().map(r=>`<div class="activity-row"><span class="activity-icon">${icon('branch',14)}</span><div class="spacer"><h4>${e(r.name)}</h4><p>${e(new Date(r.time).toLocaleString())} · ${r.snapshot.nodes.length} components</p></div>${b('Restore','restore-revision','undo','small',`data-id="${r.id}"`)}</div>`).join(''):empty('No saved baselines','Baseline snapshots are stored in this workspace.')}</div></div></section>`;}
 return top+`<section class="pid-workspace"><aside class="pid-explorer"><div class="explorer-title">DRAWING EXPLORER${ib('New drawing','new-drawing','plus')}</div><div class="explorer-content">${state.diagrams.map(d=>`<button class="tree-sheet ${d.id===diagram.id?'':'inactive'}" data-action="select-diagram" data-id="${d.id}">${icon('file',16)}<span><b>${e(d.number)}</b><small>${e(d.name)}</small><small>Revision ${e(d.revision)} ${d.id===diagram.id?'· Active':''}</small></span></button>`).join('')}</div><div class="explorer-title">LAYERS${icon('layers',13)}</div><div class="explorer-content"><label class="layer-row"><input type="checkbox" id="layer-labels" checked><span class="layer-dot blue"></span>Labels & tags<span class="count">${diagram.nodes.length}</span></label><label class="layer-row"><input type="checkbox" id="layer-signals" checked><span class="layer-dot teal"></span>Signals<span class="count">${diagram.edges.filter(e=>e.kind==='signal').length}</span></label><label class="layer-row"><input type="checkbox" id="layer-grid" checked><span class="layer-dot"></span>Drawing grid</label><div class="layer-row"><span class="layer-dot amber"></span>Needs review<span class="count">${diagram.nodes.filter(n=>n.status!=='verified').length}</span></div></div><div class="explorer-title">SYMBOL LIBRARY${icon('plus',13)}</div><div class="explorer-content"><div class="symbol-list">${[['pump','Pump'],['tank','Vessel'],['exchanger','Exchanger'],['valve','Valve'],['control','Control valve'],['instrument','Instrument']].map(([type,label])=>`<button class="symbol-button" data-action="tool" data-value="add:${type}" title="Place ${label}">${icon(type==='control'?'valve':type,22)}${label}</button>`).join('')}</div><div style="margin-top:8px">${b('All symbols','symbol-library','grid','small wide')}</div></div><div class="explorer-tip">${icon('info',12)} &nbsp; Select a symbol, then click the drawing to place it.<br><br><kbd>V</kbd> Select &nbsp; <kbd>P</kbd> Pipe<br><kbd>F</kbd> Fit &nbsp; <kbd>R</kbd> Rotate</div></aside><div class="pid-center"><div class="toolbar"><div class="toolbar-group">${ib('Select (V)','tool','cursor',true,'data-value="select"')}${ib('Pan (H)','tool','hand',false,'data-value="pan"')}<span class="toolbar-separator"></span>${ib('Draw pipe (P): click two components','tool','branch',false,'data-value="pipe"')}${ib('Connect signal: click two components','tool','link',false,'data-value="signal"')}${ib('Add component','add-component','plus')}<span class="toolbar-separator"></span>${ib('Undo (Ctrl/Cmd Z)','undo','undo')}${ib('Redo (Ctrl/Cmd Shift Z)','redo','redo')}${ib('Rotate selection (R)','rotate','rotate',false,'class="mobile-hide"')}${ib('Delete selection','delete-selection','trash',false,'class="mobile-hide"')}</div><div class="toolbar-group">${diagram.background?b('Analyze image','vision-analyze','spark','small'):b('Trace flow','trace','flow','small')}${b('Run checks','validate','checkCircle','small')}<span class="inspector-toggle">${ib('Toggle component inspector','mobile-inspector','settings')}</span></div></div><div class="drawing-stage" id="drawing-stage"><div class="canvas-chip">${icon('file',12)}<b>${e(diagram.number)}</b><span>REV ${e(diagram.revision)}</span>${badge(diagram.background?'Imported source':'Sample drawing','blue')}</div><div class="canvas-footer"><span class="canvas-hint">Scroll to zoom · Drag canvas to pan · Export a backup</span><div class="zoom-controls">${ib('Zoom out','zoom-out','minus')}<span class="zoom-label" id="zoom-label">Fit</span>${ib('Zoom in','zoom-in','plus')}<span class="toolbar-separator"></span>${ib('Fit drawing (F)','fit','fit')}</div></div></div><section class="findings-dock"><div class="findings-head"><div>${icon('warning',13)}<h4 style="font-size:10px">Review findings</h4><span class="count" id="findings-count">${findings.length}</span><span class="muted" style="font-size:9px;margin-left:7px">Structural checks · not a safety assessment</span></div><button class="text-button" data-action="ask" data-question="Explain the review findings" style="font-size:9px">Explain with assistant ${icon('spark',12)}</button></div><div class="finding-list" id="finding-list">${findingsRows(findings)}</div></section></div><aside class="inspector" id="inspector">${inspectorView(state,ui,diagram)}</aside></section>`;
}
export function componentTable(diagram,ui){const q=(ui.componentFilter||'').toLowerCase(),rows=diagram.nodes.filter(n=>[n.tag,n.name,n.type].join(' ').toLowerCase().includes(q));return table(rows,[{key:'tag',label:'Tag',render:v=>`<span class="tag-badge">${e(v)}</span>`},{key:'name',label:'Description'},{key:'type',label:'Symbol',render:v=>e(SYMBOLS[v]?.label||v)},{key:'status',label:'Review state',render:v=>badge(v,v)},{key:'lineClass',label:'Line class'},{key:'source',label:'Provenance'}],{rowAction:'focus-component'});}
export function findingsRows(findings){return findings.length?findings.map(f=>`<div class="finding-row ${f.severity}" data-action="focus-finding" data-id="${e(f.node||'')}" tabindex="0">${icon(f.severity==='error'?'warning':'info',13)}<span class="tag">${e(f.tag)}</span><span class="finding-title">${e(f.title)}</span><span class="finding-detail">${e(f.detail)}</span>${badge(f.severity,f.severity)}${icon('chevron',11)}</div>`).join(''):`<div class="empty" style="padding:25px">${icon('checkCircle',22)}<p>No findings from the implemented structural rules.</p></div>`;}
export function inspectorView(state,ui,d){if(ui.selectedEdge){const edge=d.edges.find(e=>e.id===ui.selectedEdge);if(!edge)return empty('Connection removed','Select another element.');return `<div class="inspector-heading"><span>CONNECTION DETAILS</span>${ib('Clear selection','clear-selection','x')}</div><div class="inspector-content"><h2>${e(edge.tag)}</h2><p class="subheading">${e(edge.kind)} connection</p><form data-form="edge"><input type="hidden" name="id" value="${edge.id}"><div class="property-section">Properties</div>${field('Line tag','tag',edge.tag)}${selectField('Connection type','kind',[['process','Process pipe'],['signal','Instrument signal']],edge.kind)}${selectField('From','from',d.nodes.map(n=>[n.id,n.tag]),edge.from)}${selectField('To','to',d.nodes.map(n=>[n.id,n.tag]),edge.to)}${field('Nominal diameter (mm)','diameter',edge.diameter,'number','min="0"')}${field('Line class','lineClass',edge.lineClass)}<label class="form-field"><span>Waypoints: [[x,y], …]</span><textarea name="points" rows="3" class="mono">${e(JSON.stringify(edge.points||[]))}</textarea></label><button class="btn primary wide" type="submit">${icon('save',13)} Save connection</button></form><div class="divider"></div>${b('Delete connection','delete-selection','trash','danger wide')}</div>`;}
 const n=d.nodes.find(n=>n.id===ui.selected);if(!n)return `<div class="inspector-heading">PROPERTIES</div>${empty('Inspect your process','Select a component or connection to review its properties and relationships.')}<div class="inspector-content">${b('Add component','add-component','plus','wide')}</div>${assistantTeaser()}`;
 const edges=d.edges.filter(e=>e.from===n.id||e.to===n.id);const trend=state.datasets.find(d=>d.id==='ds-telemetry')?.rows.filter(r=>r.tag===n.tag).slice(-25).map(r=>r.pressure)||[];
 return `<div class="inspector-heading"><span>COMPONENT DETAILS</span><div>${ib('Duplicate component','duplicate','copy')}${ib('Clear selection','clear-selection','x')}</div></div><div class="inspector-content"><div class="object-heading"><span class="pill-icon">${icon(n.type==='control'||n.type==='check'?'valve':n.type,23)}</span><div><h2>${e(n.tag)}</h2><p>${e(SYMBOLS[n.type]?.label||'Unclassified component')}</p></div></div><div class="row justify">${badge(n.status==='verified'?'Verified component':'Needs review',n.status)}<span class="tiny muted">${edges.length} connections</span></div>${n.operatingPressure!=null?`<div class="mini-metric"><div class="mini-metric-label">OPERATING PRESSURE · STORED VALUE</div><div class="mini-metric-value">${e(n.operatingPressure)} <small>bar</small></div>${trend.length?chart(trend,{mini:true,width:100,height:40}):''}<div class="tiny muted" style="font-size:8px;margin-top:5px">${trend.length?'Trend: synthetic sample observations':'Not a live measurement'}</div></div>`:''}<form data-form="component"><input type="hidden" name="id" value="${n.id}"><div class="property-section">Object properties</div>${field('Equipment tag','tag',n.tag,'text','required maxlength="80"')}${field('Description','name',n.name,'text','required')}${selectField('Symbol','type',Object.entries(SYMBOLS).map(([k,v])=>[k,v.label]),n.type)}<div class="form-grid">${field('Line class','lineClass',n.lineClass||'')}${field('Size (mm)','diameter',n.diameter||0,'number','min="0"')}${field('Design (bar)','designPressure',n.designPressure??'','number','step="any" min="0"')}${field('Operating (bar)','operatingPressure',n.operatingPressure??'','number','step="any" min="0"')}</div>${['valve','control','check'].includes(n.type)?`<label class="checkbox-label mb"><input type="checkbox" name="closed" ${n.closed?'checked':''}>Closed for graph tracing</label>`:''}<div class="actions"><button class="btn small primary" type="submit">${icon('save',12)} Save changes</button>${n.status!=='verified'?b('Verify','verify-component','check','small teal'):b('Mark for review','unverify-component','edit','small ghost')}</div></form><div class="property-section">Source & lineage</div><div class="source-card">${icon('file',19)}<div>${e(d.number)} <small>${e(n.source||'Manual model')} · Rev ${e(d.revision)}</small></div></div><div class="property-line"><span class="label">Ontology relationship</span><button class="text-button" data-action="object-from-component" data-id="${n.id}" style="font-size:9px">Explore object ${icon('upRight',10)}</button></div><div class="property-line"><span class="label">Connected objects</span><button class="text-button" data-action="trace" style="font-size:9px">Trace downstream ${icon('flow',10)}</button></div></div>${assistantTeaser(n.tag)}`;
}
function assistantTeaser(tag='this drawing'){return `<div class="assistant-teaser"><h4>${icon('spark',15)} Stratum assistant</h4><p>Explore components, follow connections, and investigate review findings.</p><button class="text-button" data-action="ask" data-question="Trace downstream from ${e(tag)}">Investigate this component ${icon('arrow',11)}</button></div>`;}
export function overviewView(s,ui,d){const f=validateDiagram(d),totalRows=s.datasets.reduce((n,d)=>n+d.rows.length,0);return heading('Operational overview','Your data, decisions, and engineering context. Connected.','home',b('Import data','import-data','upload')+b('Open P&ID Studio','go-pid','pid','primary'))+`<section class="content-scroll"><div class="row justify mb"><div class="row">${badge('Northline / Utilities','blue')}<span class="tiny muted">Sample operational workspace</span></div><span class="tiny muted">Updated ${e(relativeDate(s.updated))}</span></div><div class="summary-grid">${metric('Ontology objects',number(s.objects.length),'Equipment, valves, instruments, and actions','network')}${metric('Connected records',number(totalRows),`${s.datasets.length} locally stored datasets`,'database')}${metric('Diagram components',number(d.nodes.length),`${d.edges.length} process and signal connections`,'pid')}${metric('Review findings',f.length,`${s.approvals.filter(a=>a.status==='pending').length} actions awaiting approval`,'shield')}</div><div class="two-col"><div class="panel"><div class="panel-head"><div><h3>Process pressure</h3><p class="subheading">Unit 100 · P-101A / E-101 · synthetic sample data</p></div><span class="chart-legend"><span class="chart-dot"></span>Pressure, bar</span></div><div class="panel-body">${chart(s.datasets.find(d=>d.id==='ds-telemetry')?.rows.slice(-96).map(r=>r.pressure)||[])}<div class="row justify mt"><span class="tiny muted">Statistical checks can be computed locally on the GPU.</span>${b('Analyze signals','analyze-telemetry','cpu','small')}</div></div></div><div class="panel"><div class="panel-head"><h3>Workspace activity</h3>${b('View all','go-observability','','ghost small')}</div>${s.audit.toReversed().slice(0,4).map(a=>`<div class="activity-row"><span class="activity-icon">${icon('clock',13)}</span><div><h4 style="font-size:10px">${e(a.action)}</h4><p>${e(a.entity)} · ${e(relativeDate(a.time))}</p></div></div>`).join('')}<div class="panel-body">${notice('No external services are connected. The current workspace is stored only in this browser.')}</div></div></div><div class="split-title"><h3>Go from insight to action</h3><span class="tiny muted">Connected workspace tools</span></div><div class="three-col">${[['pid','pid','P&ID intelligence','Edit drawings, validate connectivity, and reconcile the equipment BOM.'],['agents','spark','Grounded operational assistant','Ask about the process model and inspect every deterministic tool result.'],['pipelines','flow','Build your data pipeline','Transform imported data through an editable, executable pipeline.']].map(([id,ic,title,desc])=>`<div class="panel card-link feature-card" data-route="${id}" tabindex="0"><span class="pill-icon">${icon(ic,20)}</span><div><h3>${title}</h3><p>${desc}</p><span class="text-button tiny">Open workspace ${icon('arrow',11)}</span></div></div>`).join('')}</div><div class="mt">${notice('Engineering sample only. Structural validation, statistical anomalies, and model-generated responses are decision-support tools—not plant control, certified design verification, or a substitute for an engineering review.','warning')}</div></section>`;}
export function dataView(s,ui){const d=s.datasets.find(d=>d.id===ui.dataset)||s.datasets[0],rows=ui.queryResults??d?.rows??[],start=(ui.dataPage||0)*100,slice=rows.slice(start,start+100),cols=[...new Set(rows.slice(0,100).flatMap(Object.keys))];return heading('Data workspace','Ingest, inspect, query, and transform your operational data.','database',b('Add document','add-document','file')+b('Import CSV / JSON','import-data','upload','primary'))+`<section class="dataset-workspace"><aside class="dataset-sidebar"><h4 class="section-title" style="margin:7px 8px 14px">DATASETS <span class="count">${s.datasets.length}</span></h4>${s.datasets.map(ds=>`<button class="dataset-item ${ds.id===d?.id?'active':''}" data-action="select-dataset" data-id="${ds.id}">${icon('database',17)}<span><b>${e(ds.name)}</b><small>${number(ds.rows.length)} records · ${e(ds.source)}</small></span></button>`).join('')}<h4 class="section-title" style="margin:24px 8px 14px">DOCUMENTS</h4>${s.documents.map(doc=>`<button class="dataset-item" data-action="view-document" data-id="${doc.id}">${icon('file',16)}<span><b>${e(doc.title)}</b><small>${doc.text.length} characters</small></span></button>`).join('')}</aside><div class="dataset-main">${d?`<div class="dataset-details"><div><h2>${e(d.name)}</h2><p class="subheading">${e(d.description||'Local dataset')} · <code>${e(d.id)}</code></p></div><div class="actions">${b('Profile','profile-data','chart','small')}${b('Add row','add-row','plus','small')}${b('Export','export-data','download','small')}</div></div><div class="query-box"><textarea id="sql-query" spellcheck="false" aria-label="SQL query">${e(ui.queryText||`SELECT * FROM ${d.id} LIMIT 100`)}</textarea><div class="query-controls"><span class="tiny muted">SELECT · WHERE · GROUP BY · ORDER BY · LIMIT · no eval()</span><div class="actions">${ui.queryResults?b('Clear result','clear-query','x','small ghost'):''}${b('Run query','run-query','play','small primary')}</div></div></div>${table(slice,cols,{cellAction:ui.queryResults?'':'edit-cell'})}<div class="table-footer"><span>${number(rows.length)} ${ui.queryResults?'result':'source'} records · ${cols.length} columns${ui.queryResults?'':' · click a cell to edit'}</span><div class="actions">${b('Previous','data-prev','','small',''+(start===0?'disabled':''))}<span>${Math.floor(start/100)+1} / ${Math.max(1,Math.ceil(rows.length/100))}</span>${b('Next','data-next','','small',start+100>=rows.length?'disabled':'')}</div></div>`:empty('No datasets','Import a CSV or JSON file to begin.')}</div></section>`;}
export function ontologyView(s,ui){const types=s.objectTypes,query=(ui.objectFilter||'').toLowerCase(),rows=s.objects.filter(o=>(!ui.objectType||o.type===ui.objectType)&&JSON.stringify(o).toLowerCase().includes(query));const selected=s.objects.find(o=>o.id===ui.objectSelected);return heading('Ontology','A connected model of the things, relationships, and actions in your operations.','network',b('New object type','new-object-type','layers')+b('Add relationship','new-link','link')+b('Create object','new-object','plus','primary'))+tabs([['graph','Object graph',s.objects.length],['table','Object explorer'],['schema','Schema',types.length]],ui.ontologyTab,'ontology')+(ui.ontologyTab==='schema'?`<section class="content-scroll"><div class="three-col">${types.map(t=>`<div class="panel"><div class="panel-head"><div class="row">${icon('layers',17)}<h3>${e(t.name)}</h3></div>${badge(`${s.objects.filter(o=>o.type===t.name).length} objects`)}</div><div class="panel-body">${t.properties.map(p=>`<div class="property-line"><code>${e(p)}</code><span class="muted tiny">property</span></div>`).join('')}${b('Edit schema','edit-type','edit','small wide mt',`data-id="${e(t.name)}"`)}</div></div>`).join('')}</div></section>`:ui.ontologyTab==='table'?`<section class="tab-content"><div class="row justify mb"><div class="search-input" style="width:260px">${icon('search',14)}<input id="object-search" placeholder="Search objects…" value="${e(ui.objectFilter||'')}"></div><select id="object-type-filter" aria-label="Object type"><option value="">All object types</option>${types.map(t=>`<option ${ui.objectType===t.name?'selected':''}>${e(t.name)}</option>`).join('')}</select></div><div class="panel" id="object-table">${objectTable(rows)}</div></section>`:`<section class="ontology-layout"><div class="minw0" style="display:flex;flex-direction:column"><div class="toolbar"><span class="tiny muted">${s.objects.length} objects · ${s.links.length} relationships · drag nodes to explore</span><div class="actions">${b('Fit graph','graph-fit','fit','small')}${b('Export graph','export-ontology','download','small')}</div></div><div class="drawing-stage ontology-graph" id="ontology-stage"></div></div><aside class="ontology-info"><h4 class="section-title">OBJECT TYPES</h4>${types.map(t=>`<div class="type-card"><div class="row">${icon(t.name==='Equipment'?'pump':t.name==='Instrument'?'instrument':t.name==='Valve'?'valve':'file',15)}${e(t.name)}</div><span class="count">${s.objects.filter(o=>o.type===t.name).length}</span></div>`).join('')}<div class="divider"></div><div id="ontology-object-info">${selected?ontologyObjectInfo(s,selected):empty('Explore the graph','Select an object to inspect its properties and linked objects.')}</div></aside></section>`);}
export function objectTable(rows){return table(rows,[{key:'tag',label:'Object tag',render:v=>`<span class="tag-badge">${e(v)}</span>`},{key:'name',label:'Name'},{key:'type',label:'Object type'},{key:'status',label:'Status',render:v=>badge(v,v==='Active'?'green':'warning')},{key:'unit',label:'Unit'},{key:'criticality',label:'Criticality'}],{rowAction:'edit-object'});}
export function ontologyObjectInfo(s,o){const links=s.links.filter(l=>l.from===o.id||l.to===o.id);return `<div class="object-heading"><span class="pill-icon">${icon(o.symbol||'network',23)}</span><div><h2>${e(o.tag||o.type)}</h2><p>${e(o.name)}</p></div></div>${badge(o.type,'blue')}<div class="property-section">Properties</div>${Object.entries(o).filter(([k])=>!['id','diagram','diagramNode','symbol','name','type'].includes(k)).map(([k,v])=>`<div class="property-line"><span class="label">${e(k)}</span><span class="truncate">${e(v)}</span></div>`).join('')}<div class="mt">${b('Edit object','edit-object','edit','small wide',`data-id="${o.id}"`)}</div><div class="property-section">Relationships · ${links.length}</div>${links.map(l=>{const other=s.objects.find(x=>x.id===(l.from===o.id?l.to:l.from));return `<div class="source-card mb" style="padding:9px;margin-bottom:7px">${icon('link',14)}<div>${e(other?.tag||'?')}<small>${e(l.type)}</small></div></div>`;}).join('')}`;}
export function pipelineView(s,ui){const p=s.pipelines.find(p=>p.id===ui.pipeline)||s.pipelines[0],n=p?.nodes.find(n=>n.id===ui.pipelineNode)||p?.nodes[0],run=ui.pipelineResult||p?.runs.at(-1);return heading('Pipeline builder','Executable data transformations, explicit lineage, and inspectable results.','flow',b('New pipeline','new-pipeline','plus')+b('Add block','add-block','plus')+b('Run pipeline','run-pipeline','play','primary'))+`<div class="toolbar"><div class="row"><select id="pipeline-select" aria-label="Select pipeline" style="font-size:10px;padding:5px">${s.pipelines.map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select>${badge(`${p.nodes.length} blocks`)}</div><div class="actions">${b('Export definition','export-pipeline','download','small')}${b('Save outputs as datasets','materialize-pipeline','database','small',!run?.outputs?.length?'disabled':'')}</div></div><section class="pipeline-layout"><div class="pipeline-main"><div class="pipeline-canvas"><div class="flow-board"><svg class="flow-connections" viewBox="0 0 1220 400">${p.nodes.flatMap(node=>(node.inputs||[]).map(id=>{const from=p.nodes.find(n=>n.id===id);return from?`<path d="M${from.x+214} ${from.y+30} C${from.x+248} ${from.y+30} ${node.x-40} ${node.y+30} ${node.x} ${node.y+30}" stroke="#9baec5" fill="none" stroke-width="1.5"/>`:'';})).join('')}</svg>${p.nodes.map(node=>`<div class="flow-node ${n?.id===node.id?'active':''}" data-action="select-block" data-id="${node.id}" style="left:${node.x}px;top:${node.y}px" tabindex="0"><div class="flow-node-head">${icon(node.type==='source'?'database':node.type==='filter'?'filter':node.type==='output'?'table':'code',17)}${e(node.name)}</div><div class="flow-node-body"><span class="badge blue" style="font-size:8px;margin-right:4px">${e(node.type)}</span>${e(node.config.expression||node.config.name||s.datasets.find(d=>d.id===node.config.dataset)?.name||node.config.group||'Configure transformation')}</div></div>`).join('')}</div></div><div class="flow-trace"><div class="panel-head" style="padding:10px 15px"><h3 style="font-size:11px">Execution trace</h3>${run?badge(`${number(run.duration,2)} ms · ${run.rows?.length??0} output rows`,'success'):badge('Not run yet')}</div>${run?table(run.trace||[],[{key:'name',label:'Block'},{key:'type',label:'Operation'},{key:'rows',label:'Rows'},{key:'duration',label:'Duration',render:v=>number(v,3)+' ms'},{key:'status',label:'Status',render:v=>badge(v,'success')}]):empty('Ready to execute','Run this pipeline to inspect every block and its output.')}</div></div><aside class="pipeline-config">${n?blockConfig(s,p,n):''}</aside></section>`;}
export function blockConfig(s,p,n){let fields='';const c=n.config;if(n.type==='source')fields=selectField('Source dataset','dataset',s.datasets.map(d=>[d.id,d.name]),c.dataset);if(['filter','derive'].includes(n.type))fields=(n.type==='derive'?field('Output column','column',c.column,'text','required'):'')+`<label class="form-field"><span>Expression</span><textarea name="expression" rows="4" spellcheck="false" class="mono" required>${e(c.expression||'')}</textarea></label>`;if(n.type==='select')fields=field('Columns (comma separated)','columns',c.columns);if(['sort','deduplicate'].includes(n.type))fields=field('Column','column',c.column)+(n.type==='sort'?selectField('Sort direction','desc',[['false','Ascending'],['true','Descending']],String(c.desc||false)):'');if(n.type==='aggregate')fields=field('Group by column','group',c.group)+selectField('Aggregate operation','op',['count','sum','avg','min','max'],c.op)+field('Value column (* for count)','column',c.column||'*')+field('Output name','as',c.as||'value');if(n.type==='join')fields=field('Left key','leftKey',c.leftKey)+field('Right key','rightKey',c.rightKey)+selectField('Join type','how',['inner','left'],c.how);if(n.type==='output')fields=field('Output dataset name','name',c.name);return `<h3>Block configuration</h3><p class="subheading mb">${e(n.type)} · ${e(n.id)}</p><form data-form="block"><input type="hidden" name="id" value="${n.id}">${field('Block name','blockName',n.name,'text','required')}${n.type!=='source'?`<label class="form-field"><span>Inputs ${n.type==='join'?'(choose two)':''}</span><select name="inputs" multiple size="${Math.min(4,p.nodes.length-1)}">${p.nodes.filter(x=>x.id!==n.id).map(x=>`<option value="${x.id}" ${n.inputs.includes(x.id)?'selected':''}>${e(x.name)}</option>`).join('')}</select></label>`:''}${fields}<button class="btn primary wide" type="submit">${icon('save',14)} Save block</button></form><div class="divider"></div>${b('Remove block','remove-block','trash','danger wide',`data-id="${n.id}"`)}<div class="mt">${notice('Expressions are parsed, not evaluated as JavaScript. Functions: abs, round, lower, upper, length, contains, coalesce, sqrt, min, max.')}</div><div class="mt">${b('Edit full definition','edit-pipeline-json','code','wide')}</div>`;}
export function chatMessages(messages=[]){return messages.length?messages.map(m=>`<article class="message ${m.role}"><div class="message-label">${icon(m.role==='user'?'grid':'spark',13)}${m.role==='user'?'YOU':'STRATUM ASSISTANT'}${m.mode?`<span class="muted" style="font-weight:400">· ${e(m.mode)}</span>`:''}</div><div class="message-body">${e(m.text)}</div>${m.citations?.length?`<div class="message-citations">${m.citations.map(c=>`<button class="citation" data-action="citation" data-kind="${c.kind}" data-id="${e(c.id)}">${icon(c.kind==='component'?'pid':c.kind==='dataset'?'database':'file',10)} ${e(c.label)}</button>`).join('')}</div>`:''}</article>`).join(''):`<div class="chat-welcome"><div class="welcome-icon">${icon('spark',27)}</div><h2>Start with your operational context.</h2><p>Explore the process model, inspect connections, and turn review findings into grounded answers.</p><div class="prompt-grid">${[['pid','Which components need review?'],['flow','Trace downstream from P-101A'],['table','Reconcile the bill of materials'],['chart','What is the operating pressure of P-101A?']].map(([ic,q])=>`<button class="prompt-card" data-action="chat-prompt" data-question="${e(q)}">${icon(ic,17)}${e(q)} ${icon('arrow',11)}</button>`).join('')}</div><p style="font-size:9px;margin-top:18px">Local mode uses explicit query rules. It is not a generative language model.</p></div>`;}
export function chatCompose(busy=false){return `<form class="chat-compose" data-form="chat"><div class="compose-box"><textarea name="question" id="chat-input" placeholder="Ask about your process, components, or documents…" aria-label="Message to assistant" rows="2" required ${busy?'disabled':''}></textarea><button class="btn primary" type="submit" title="Send message" aria-label="Send message" ${busy?'disabled':''}>${icon('send',16)}</button></div><div class="compose-note"><span>Read-only answers · actions require human approval</span><span>Enter to send</span></div></form>`;}
export function agentView(s,ui){const agent=s.agents[0],thread=s.threads.find(t=>t.id===ui.thread),messages=thread?.messages||[],last=messages.filter(m=>m.role==='assistant').at(-1);return heading('Agent studio','Build assistants grounded in your ontology, documents, and engineering context.','spark',b('Configure agent','configure-agent','settings')+b('New conversation','new-thread','plus','primary'))+`<section class="agent-layout"><aside class="agent-context"><h4 class="section-title">RETRIEVAL CONTEXT</h4><div class="context-box"><div class="context-title">${icon('network',15)}Ontology objects</div><small>${s.objects.length} local objects · ${s.objectTypes.length} types</small></div><div class="context-box"><div class="context-title">${icon('pid',15)}Active engineering drawing</div><small>${e(s.diagrams.find(d=>d.id===s.activeDiagram)?.number)} · components and connectivity</small></div><div class="context-box"><div class="context-title">${icon('book',15)}Engineering documents</div><small>${s.documents.length} documents · BM25 lexical retrieval</small></div><div class="divider"></div><h4 class="section-title">AVAILABLE READ TOOLS</h4>${agent.tools.map(t=>`<div class="tool-row">${icon('checkCircle',12)}<code>${e(t)}</code></div>`).join('')}<div class="divider"></div><h4 class="section-title">CONVERSATIONS</h4>${s.threads.toReversed().slice(0,10).map(t=>`<button class="dataset-item ${ui.thread===t.id?'active':''}" data-action="select-thread" data-id="${t.id}"><span><b>${e(t.title)}</b><small>${t.messages.length} messages</small></span></button>`).join('')||'<p class="tiny muted">New conversations are saved locally.</p>'}</aside><div class="chat-center"><div class="chat-top"><div class="row">${icon('spark',16)}<span class="small strong">${e(agent.name)}</span></div><select id="assistant-mode" aria-label="Assistant mode" style="font-size:10px;padding:5px"><option value="local" ${ui.modelMode==='local'?'selected':''}>Local deterministic</option><option value="remote" ${ui.modelMode==='remote'?'selected':''}>Configured external model</option></select></div><div class="chat-messages" id="chat-messages">${chatMessages(messages)}${ui.chatBusy?'<div class="loading-inline"><span class="spinner"></span>Running grounded query…</div>':''}</div>${chatCompose(ui.chatBusy)}</div><aside class="agent-trace"><h4 class="section-title">EXECUTION INSPECTOR</h4>${last?`<div class="trace-card"><h4>${icon('grid',13)}Request context</h4><p>${e(last.mode)} · ${last.citations?.length||0} evidence references</p></div><div class="trace-arrow">↓</div>${last.traces?.map(t=>`<div class="trace-card"><h4>${icon('code',13)}${e(t.tool)}</h4><p>${e(t.result)}</p><p style="margin-top:6px">${number(t.duration,2)} ms</p></div><div class="trace-arrow">↓</div>`).join('')||''}<div class="trace-card"><h4>${icon('checkCircle',13)}Response delivered</h4><p>No operational actions executed. This log shows tool execution, not hidden model reasoning.</p></div>`:notice('Tool inputs, result summaries, and evidence references appear here after each query.')}<div class="divider"></div><h4 class="section-title">ACTION BOUNDARY</h4><p class="tiny muted" style="line-height:1.8">Assistant replies cannot modify the ontology, approve changes, or operate equipment. Use the reviewed actions workflow for writes.</p>${b('Open actions','go-logic','arrow','small wide mt')}</aside></section>`;}
export function logicView(s){return heading('Logic & actions','Prepare operational changes, inspect their payloads, and route them for review.','code',b('New work order','new-work-order','plus','primary'))+`<section class="content-scroll"><div class="two-col"><div class="panel"><div class="panel-head"><h3>Available action types</h3>${badge('Human-in-the-loop','blue')}</div><div class="panel-body stack"><div class="model-card" style="margin:0"><h3>${icon('network',20)}Publish diagram objects</h3><p>Stage component and relationship upserts from the active P&ID. Review the exact snapshot before committing the change.</p>${b('Prepare publication','publish','arrow','small primary')}</div><div class="model-card" style="margin:0"><h3>${icon('file',20)}Create engineering work order</h3><p>Create a work order linked to a component. The action stays pending until a reviewer explicitly approves it.</p>${b('Prepare work order','new-work-order','arrow','small')}</div><div class="model-card" style="margin:0"><h3>${icon('edit',20)}Propose object property changes</h3><p>Select an ontology object and stage a property update with a before/after preview.</p>${b('Prepare change','stage-object-edit','arrow','small')}</div></div></div><div class="panel"><div class="panel-head"><h3>Pending action queue</h3>${badge(`${s.approvals.filter(a=>a.status==='pending').length} pending`,'pending')}</div>${s.approvals.filter(a=>a.status==='pending').length?s.approvals.filter(a=>a.status==='pending').map(a=>approvalCard(a)).join(''):empty('No actions awaiting review','Prepare a publication or work order to start the approval workflow.')}<div class="panel-body">${notice('This is a local review workflow, not authenticated multi-user access control. Approval never sends commands to a plant or an external enterprise system.','warning')}</div></div></div></section>`;}
function approvalCard(a){return `<div class="review-card"><div class="row justify">${badge(a.kind,'blue')}${badge(a.status,a.status)}</div><h3>${e(a.title)}</h3><p>${e(a.summary||'Review this proposed operational change.')}</p><div class="actions">${b('Inspect payload','inspect-approval','eye','small',`data-id="${a.id}"`)}${a.status==='pending'?b('Approve','approve','check','small primary',`data-id="${a.id}"`)+b('Reject','reject','x','small',`data-id="${a.id}"`):''}</div></div>`;}
export function evaluationView(s){const last=s.evaluationRuns.at(-1);return heading('Evaluations','Test grounded answers against explicit expectations and compare runs.','flask',b('Add test case','add-eval','plus')+b('Run evaluation suite','run-evals','play','primary'))+`<section class="content-scroll"><div class="summary-grid">${metric('Test cases',s.evaluations.length,'Editable question / expected text assertions','flask')}${metric('Latest pass rate',last?`${Math.round(last.passed/Math.max(1,last.total)*100)}%`:'—',last?`${last.passed} of ${last.total} assertions passed`:'Run the suite to establish a baseline','checkCircle')}${metric('Evaluation runs',s.evaluationRuns.length,'Stored locally with actual outputs','clock')}${metric('Execution mode','Local','Deterministic assistant · substring assertions','cpu')}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Test case definitions</h3>${badge('Editable')}</div>${table(s.evaluations,[{key:'question',label:'Question'},{key:'expected',label:'Expected answer contains'},{key:'id',label:'Edit',render:v=>b('Edit','edit-eval','edit','small',`data-id="${v}"`)}])}</div><div class="panel"><div class="panel-head"><h3>Latest run</h3>${last?badge(new Date(last.time).toLocaleTimeString()):badge('Not run')}</div>${last?last.results.map(r=>`<div class="eval-result"><h3>${icon(r.passed?'checkCircle':'warning',15)}${e(r.question)}</h3><p>Expected: <code>${e(r.expected||'')}</code> · ${number(r.duration,2)} ms</p><p>${e((r.error||r.actual||'').slice(0,210))}</p><div style="margin-top:9px">${badge(r.passed?'Passed':'Failed',r.passed?'success':'failed')}</div></div>`).join(''):empty('Ready to evaluate','Run the local assistant against every test case. Results are not simulated.')}</div></div><div class="panel"><div class="panel-head"><h3>Run history</h3>${b('Export results','export-evals','download','small')}</div>${table(s.evaluationRuns.toReversed(),[{key:'time',label:'Executed',render:v=>e(new Date(v).toLocaleString())},{key:'passed',label:'Passed'},{key:'total',label:'Total'},{key:'id',label:'Run ID'}],{empty:'No evaluations have been executed yet.'})}</div></section>`;}
export function applicationsView(s){const d=s.diagrams.find(d=>d.id===s.activeDiagram)||s.diagrams[0],counts={objects:s.objects.length,components:d.nodes.length,findings:validateDiagram(d).length,records:s.datasets.reduce((n,d)=>n+d.rows.length,0)};return heading('Application workshop','Compose an operational dashboard from your local data and ontology.','grid',b('Add widget','add-widget','plus','primary'))+`<section class="content-scroll"><div class="row justify mb"><div><h2>Utilities operations console</h2><p class="subheading">Editable application · widgets bind to current workspace data</p></div>${badge('Local application','blue')}</div><div class="app-widgets">${s.dashboard.map((w,i)=>w.type==='chart'?`<div class="panel chart-widget"><div class="panel-head"><div><h3>${e(w.title)}</h3><p class="subheading">${e(s.datasets.find(d=>d.id===w.source)?.name||'Dataset')} · pressure · sample data</p></div><div class="widget-controls">${ib('Move widget earlier','move-widget','undo',false,`data-id="${w.id}"`)}${ib('Edit widget','edit-widget','edit',false,`data-id="${w.id}"`)}${ib('Remove widget','remove-widget','trash',false,`data-id="${w.id}"`)}</div></div><div class="panel-body">${chart(s.datasets.find(d=>d.id===w.source)?.rows.map(r=>Number(r[w.column||'pressure'])).filter(Number.isFinite)||[])}</div></div>`:`<div class="metric-card"><div class="metric-top"><span>${e(w.title)}</span><div class="widget-controls">${ib('Edit widget','edit-widget','edit',false,`data-id="${w.id}"`)}${ib('Remove widget','remove-widget','trash',false,`data-id="${w.id}"`)}</div></div><div class="metric-value">${counts[w.source]??0}</div><div class="metric-note">Bound to ${e(w.source)}</div></div>`).join('')}</div><div class="mt">${notice('Widgets are live views of the local workspace. The workshop supports count metrics and numeric line charts; it is not a general-purpose UI framework.')}</div></section>`;}
export function automationsView(s){return heading('Automations','Event-driven checks and manually triggered jobs, with an inspectable run history.','bolt',b('Create automation','new-automation','plus','primary'))+`<section class="content-scroll"><div class="mb">${notice('Local automations run only while this app is open. Diagram-change triggers run structural checks. They do not start background server jobs or execute plant actions.')}</div><div class="stack">${s.automations.map(a=>`<div class="panel automaton"><span class="pill-icon">${icon('bolt',22)}</span><div><h3>${e(a.name)}</h3><p>Trigger: ${e(a.trigger)} → ${e(a.action)} · ${a.lastRun?'Last run '+e(relativeDate(a.lastRun)):'Not run yet'}</p></div><div class="actions">${badge(a.enabled?'Enabled':'Disabled',a.enabled?'green':'')}<input class="switch" type="checkbox" data-automation="${a.id}" ${a.enabled?'checked':''} aria-label="Enable ${e(a.name)}">${b('Run now','run-automation','play','small',`data-id="${a.id}"`)}${b('Edit','edit-automation','edit','small',`data-id="${a.id}"`)}</div></div>`).join('')}</div><div class="panel mt"><div class="panel-head"><h3>Automation execution log</h3></div>${table(s.runs.filter(r=>r.kind==='automation').toReversed(),[{key:'time',label:'Time',render:v=>e(new Date(v).toLocaleString())},{key:'name',label:'Automation'},{key:'status',label:'Status',render:v=>badge(v,v)},{key:'summary',label:'Result'}],{empty:'No automation runs yet.'})}</div></section>`;}
export function observabilityView(s){const runs=s.runs,failed=runs.filter(r=>r.status==='failed').length;return heading('Observability','Inspect pipeline runs, local computations, and the workspace audit trail.','chart',b('Export audit log','export-audit','download'))+`<section class="content-scroll"><div class="summary-grid">${metric('Executions',runs.length,'Actual recorded runs','play')}${metric('Successful',runs.filter(r=>r.status==='success').length,'Completed local jobs','checkCircle')}${metric('Failed',failed,'Errors retained for inspection','warning')}${metric('Audit events',s.audit.length,'Local hash-linked history','shield')}</div><div class="panel mb"><div class="panel-head"><h3>Execution history</h3></div>${table(runs.toReversed(),[{key:'name',label:'Operation'},{key:'kind',label:'Engine'},{key:'time',label:'Started',render:v=>e(new Date(v).toLocaleString())},{key:'duration',label:'Duration',render:v=>v!=null?number(v,2)+' ms':'—'},{key:'status',label:'Result',render:v=>badge(v,v)},{key:'summary',label:'Details'}],{empty:'Run a pipeline, evaluation, or signal analysis to create execution records.'})}</div><div class="panel"><div class="panel-head"><div><h3>Workspace audit log</h3><p class="subheading">Local change history. Not tamper-proof, authenticated, or an enterprise compliance log.</p></div>${badge('Local only')}</div><div class="audit-list">${table(s.audit.toReversed(),[{key:'time',label:'Time',render:v=>e(new Date(v).toLocaleString())},{key:'action',label:'Action'},{key:'entity',label:'Entity'},{key:'hash',label:'Entry digest',render:v=>`<code>${e(v)}</code>`},{key:'previous',label:'Previous digest',render:v=>`<code>${e(v)}</code>`}])}</div></div></section>`;}
export function governanceView(s){return heading('Governance','Review proposed changes and understand the local workspace trust boundary.','shield',b('Export approval history','export-approvals','download'))+`<section class="content-scroll"><div class="two-col"><div class="panel"><div class="panel-head"><h3>Human review queue</h3>${badge(`${s.approvals.filter(a=>a.status==='pending').length} pending`,'pending')}</div>${s.approvals.length?s.approvals.toReversed().map(approvalCard).join(''):empty('No proposed changes','Use Publish to ontology or Logic & actions to stage changes for review.')}</div><div class="stack"><div class="panel"><div class="panel-head"><h3>Workspace policy</h3>${icon('shield',17)}</div><div class="panel-body"><div class="property-line"><span class="label">Model access</span>${badge(s.settings.shareContext?'Explicitly enabled':'Not authorized',s.settings.shareContext?'warning':'green')}</div><div class="property-line"><span class="label">Agent writes</span>${badge('Disabled','green')}</div><div class="property-line"><span class="label">Publication</span>${badge('Human review required','blue')}</div><div class="property-line"><span class="label">Data storage</span><span>Browser IndexedDB</span></div><div class="property-line"><span class="label">Authentication</span>${badge('Not provided','warning')}</div><div class="property-line"><span class="label">Current local role</span><span>${e(s.settings.role)}</span></div><div class="mt">${b('Configure local settings','go-settings','settings','wide')}</div></div></div>${notice('Local viewer/editor modes prevent accidental edits; they do not provide security against a user with browser or filesystem access. Enterprise identity, row-level permissions, trusted audit storage, and multi-user authorization require a backend.','warning')}</div></div></section>`;}
export function settingsView(s,ui,gpu){return heading('Models & settings','Explicit connections, local workspace preferences, and engine diagnostics.','settings',b('Export workspace','export-workspace','download'))+`<section class="content-scroll"><div class="settings-grid"><div class="panel"><div class="panel-head"><div><h3>External model connection</h3><p class="subheading">Bring a chat-completions-compatible endpoint. Nothing is connected by default.</p></div>${badge(s.settings.endpoint?'Configured':'Not connected',s.settings.endpoint?'blue':'')}</div><form class="panel-body" data-form="settings">${field('Full chat-completions endpoint URL','endpoint',s.settings.endpoint,'url','placeholder="https://your-gateway.example/v1/chat/completions"')}${field('Text model identifier','model',s.settings.model,'text','placeholder="Your deployed model ID"')}${field('Vision model identifier (optional)','visionModel',s.settings.visionModel,'text','placeholder="A deployed image-capable model"')}<label class="form-field"><span>API key · kept in memory until page reload</span><input type="password" name="apiKey" value="${e(ui.apiKey||'')}" autocomplete="off" placeholder="Never written to local storage"></label><label class="checkbox-label"><input type="checkbox" name="shareContext" ${s.settings.shareContext?'checked':''}><span>I authorize sending selected engineering context and uploaded images to this endpoint when I explicitly run an external model.</span></label><div class="mt">${notice('Use a trusted gateway that permits browser CORS requests. Production credentials belong on a secure backend. Model calls may incur provider charges. No model weights are bundled.','warning')}</div><div class="actions mt"><button class="btn primary" type="submit">${icon('save',13)}Save connection settings</button>${b('Test connection','test-model','bolt')}</div></form></div><div class="stack"><div class="panel"><div class="panel-head"><h3>Rendering & compute</h3>${badge(gpu.mode,gpu.mode==='WebGPU'?'green':'warning')}</div><div class="panel-body"><div class="property-line"><span class="label">Engine</span><span>${e(gpu.mode)}</span></div><p class="tiny muted" style="margin:8px 0 15px">${e(gpu.reason)}</p><p>Retained vector batches, GPU viewport transforms, Canvas text overlay, and a parallel WGSL z-score compute kernel. Rendering occurs on demand.</p><div class="actions mt">${b('Run compute diagnostics','engine-diagnostics','cpu')}${b('Analyze sample telemetry','analyze-telemetry','chart')}</div></div></div><div class="panel"><div class="panel-head"><h3>Workspace preferences</h3></div><form class="panel-body" data-form="preferences">${field('Workspace name','name',s.name,'text','required')}${selectField('Theme','theme',[['light','Light'],['dark','Dark']],s.theme)}${selectField('Local edit mode (not authentication)','role',[['editor','Editor — permit local changes'],['viewer','Viewer — prevent accidental edits']],s.settings.role)}<button class="btn" type="submit">${icon('save',13)}Save preferences</button></form></div><div class="panel"><div class="panel-head"><h3>Data portability</h3></div><div class="panel-body"><p>Workspace exports contain diagrams, datasets, documents, conversations, settings, and local history. They never include the in-memory API key.</p><div class="actions mt">${b('Import workspace','import-workspace','upload')}${b('Reset sample workspace','reset-workspace','rotate','danger')}</div></div></div></div></div></section>`;}
export const renderView=(route,s,ui,d,gpu)=>({pid:()=>pidView(s,ui,d),overview:()=>overviewView(s,ui,d),data:()=>dataView(s,ui),ontology:()=>ontologyView(s,ui),pipelines:()=>pipelineView(s,ui),agents:()=>agentView(s,ui),logic:()=>logicView(s),evaluations:()=>evaluationView(s),applications:()=>applicationsView(s),automations:()=>automationsView(s),observability:()=>observabilityView(s),governance:()=>governanceView(s),settings:()=>settingsView(s,ui,gpu)}[route]||(()=>overviewView(s,ui,d)))();
